//! Decode and encode end to end: our own encoders round-trip through our own decoders, and every
//! container is exercised with files generated by the repo's ffmpeg oracle (skipped, loudly, when
//! ffmpeg is absent; `FILMCRAFT_REQUIRE_ORACLES=1` forbids skipping).

use std::io::Cursor;
use std::process::Command;
use std::sync::atomic::{AtomicU64, Ordering};

use filmcraft_lib::{
    AudioOptions, Control, Demuxer, Encoder, EncoderOptions, ErrorKind, FrameRate, Limits, MediaFile, OutputContainer, RateControl, RemuxOptions,
    SegmentOptions, Tick, VideoCodec, VideoOptions, encode_gif, encode_png, encode_wav, probe_bytes, remux_to_vec, segment,
};

const W: u32 = 64;
const H: u32 = 48;

fn picture(i: u32) -> Vec<u8> {
    let mut px = vec![0u8; (W * H * 4) as usize];
    for (n, p) in px.as_chunks_mut::<4>().0.iter_mut().enumerate() {
        let (x, y) = ((n as u32) % W, (n as u32) / W);
        p.copy_from_slice(&[(x * 3 + i * 6) as u8, (y * 4) as u8, ((x + y) * 2) as u8, 255]);
    }
    px
}

fn psnr(a: &[u8], b: &[u8]) -> f64 {
    assert_eq!(a.len(), b.len());
    let mut se = 0f64;
    let mut n = 0f64;
    for (x, y) in a.as_chunks::<4>().0.iter().zip(b.as_chunks::<4>().0.iter()) {
        for c in 0..3 {
            let d = f64::from(x[c]) - f64::from(y[c]);
            se += d * d;
            n += 1.0;
        }
    }
    if se == 0.0 { 99.0 } else { 10.0 * (255.0f64 * 255.0 / (se / n)).log10() }
}

fn encode_video(codec: VideoCodec, profile: Option<&str>, quicktime: bool, frames: u32) -> Vec<u8> {
    let mut v = VideoOptions::new(codec, W, H, FrameRate::FPS_25);
    v.rate_control = RateControl::Crf(16.0);
    v.profile = profile.map(str::to_string);
    v.keyframe_interval = Some(5);
    let mut o = EncoderOptions::new(Some(v), None);
    o.quicktime = quicktime;
    let mut enc = Encoder::new(Cursor::new(Vec::new()), o).expect("encoder");
    for i in 0..frames {
        enc.push_rgba(&picture(i)).expect("push");
    }
    enc.finish(&Control::default()).expect("finish").0.into_inner()
}

fn open(name: &str, bytes: Vec<u8>) -> MediaFile {
    MediaFile::open_bytes(name, bytes, &Limits::default(), &Control::default()).unwrap_or_else(|e| panic!("{name}: {e}"))
}

#[test]
fn every_builtin_video_encoder_round_trips_through_the_decoder() {
    let cases: [(&str, VideoCodec, Option<&str>, bool, f64); 5] = [
        ("h264.mp4", VideoCodec::H264, None, false, 28.0),
        ("prores.mov", VideoCodec::ProRes, Some("hq"), true, 38.0),
        ("dnxhr.mov", VideoCodec::DnxHr, Some("hq"), true, 33.0),
        ("mjpeg.mov", VideoCodec::Mjpeg, None, true, 28.0),
        ("apv.mov", VideoCodec::Apv, None, true, 33.0),
    ];
    for (name, codec, profile, qt, min_psnr) in cases {
        let file = open(name, encode_video(codec, profile, qt, 6));
        let info = file.info();
        let v = info.video.as_ref().unwrap_or_else(|| panic!("{name}: no video"));
        assert_eq!((v.width, v.height), (W, H), "{name}");
        for i in [0u32, 3, 5] {
            let t = FrameRate::FPS_25.tick_of(i64::from(i));
            let f = file.frame_at(t, &Control::default()).unwrap_or_else(|e| panic!("{name} frame {i}: {e}"));
            let p = psnr(&f.to_rgba8(), &picture(i));
            assert!(p > min_psnr, "{name} frame {i}: PSNR {p:.1} dB");
        }
    }
}

#[test]
fn probe_gives_the_exact_frame_count_and_timestamps() {
    let bytes = encode_video(VideoCodec::H264, None, false, 12);
    let p = probe_bytes("x.mp4", bytes, &Limits::default(), &Control::default()).expect("probe");
    let n = p.frame_count().expect("count");
    assert!(n.is_exact());
    assert_eq!(n.value(), 12);
    let ts = p.video_timestamps().expect("timestamps");
    assert_eq!(ts.len(), 12);
    assert_eq!(ts[1] - ts[0], FrameRate::FPS_25.frame_duration());
    assert!(ts.windows(2).all(|w| w[0] < w[1]));
}

#[test]
fn h264_bframes_and_every_rate_control_decode() {
    for rc in [RateControl::Cbr { kbps: 800 }, RateControl::Vbr { target_kbps: 600, max_kbps: 1000 }, RateControl::Crf(30.0)] {
        let mut v = VideoOptions::new(VideoCodec::H264, W, H, FrameRate::FPS_30);
        v.rate_control = rc;
        let mut enc = Encoder::new(Cursor::new(Vec::new()), EncoderOptions::new(Some(v), None)).expect("encoder");
        for i in 0..8 {
            enc.push_rgba(&picture(i)).expect("push");
        }
        let bytes = enc.finish(&Control::default()).expect("finish").0.into_inner();
        let f = open("rc.mp4", bytes).frame_number(7, &Control::default()).expect("last frame");
        assert!(psnr(&f.to_rgba8(), &picture(7)) > 18.0, "{rc:?}");
    }
}

#[test]
fn two_pass_h264_uses_the_analysis() {
    use filmcraft_lib::{VideoFrame, analyze_h264};
    let mut v = VideoOptions::new(VideoCodec::H264, W, H, FrameRate::FPS_30);
    v.rate_control = RateControl::TwoPass { target_kbps: 500, max_kbps: 900 };
    let frames = || (0..8).map(|i| VideoFrame::rgba8(W, H, picture(i)));
    let fp = analyze_h264(&v, frames(), &Control::default()).expect("analysis");
    assert!(fp.to_text().starts_with("h264enc-pass1"));
    // the second pass without the analysis is refused
    assert!(Encoder::new(Cursor::new(Vec::new()), EncoderOptions::new(Some(v.clone()), None)).is_err());
    v.first_pass = Some(fp);
    let mut enc = Encoder::new(Cursor::new(Vec::new()), EncoderOptions::new(Some(v), None)).expect("encoder");
    for f in frames() {
        enc.push_frame(&f).expect("push");
    }
    let bytes = enc.finish(&Control::default()).expect("finish").0.into_inner();
    assert_eq!(probe_bytes("t.mp4", bytes, &Limits::default(), &Control::default()).expect("probe").frame_count().map(|c| c.value()), Some(8));
}

#[test]
fn audio_survives_aac_and_pcm() {
    let tone: Vec<f32> = (0..48_000).map(|i| (i as f32 * 2.0 * std::f32::consts::PI * 440.0 / 48_000.0).sin() * 0.5).collect();
    for (name, codec_aac) in [("aac", true), ("pcm", false)] {
        let mut a = AudioOptions::aac(48_000, 2);
        if !codec_aac {
            a.codec = filmcraft_lib::AudioCodec::Pcm16;
        }
        let mut enc = Encoder::new(Cursor::new(Vec::new()), EncoderOptions::new(None, Some(a))).expect("encoder");
        // odd chunk sizes on purpose
        for chunk in tone.chunks(3333) {
            enc.push_audio(&[chunk.to_vec(), chunk.to_vec()]).expect("push audio");
        }
        let (bytes, rep) = enc.finish(&Control::default()).expect("finish");
        assert_eq!(rep.audio_samples, 48_000);
        let file = open("a.m4a", bytes.into_inner());
        let pcm = file.audio_window(0, 4800, 9600, 48_000, &Control::default()).expect("window");
        assert_eq!((pcm.channel_count(), pcm.frames()), (2, 9600), "{name}");
        let rms = (pcm.channels[0].iter().map(|s| s * s).sum::<f32>() / 9600.0).sqrt();
        assert!((rms - 0.5 / 2f32.sqrt()).abs() < 0.05, "{name}: rms {rms}");
    }
}

#[test]
fn gif_png_and_wav_helpers_produce_files_the_decoder_reads() {
    let frames: Vec<Vec<u8>> = (0..5).map(picture).collect();
    let gif = encode_gif(W, H, FrameRate::FPS_25, frames.iter().map(Vec::as_slice), &Control::default()).expect("gif");
    let f = open("a.gif", gif);
    assert_eq!(f.info().video.as_ref().map(|v| (v.width, v.height)), Some((W, H)));
    assert!(f.info().duration > Tick::ZERO);
    let png = encode_png(W, H, &frames[0]).expect("png");
    let f = open("a.png", png);
    assert!(psnr(&f.frame_at(Tick::ZERO, &Control::default()).expect("still").to_rgba8(), &frames[0]) > 40.0);
    let wav = encode_wav(&[0.0, 0.5, -0.5, 0.25, 0.0, 0.0], 2, 8000, false).expect("wav");
    let f = open("a.wav", wav);
    let a = f.audio_window(0, 0, 3, 8000, &Control::default()).expect("wav audio");
    assert!((a.channels[0][1] + 0.5).abs() < 1e-3 && (a.channels[1][0] - 0.5).abs() < 1e-3);
    assert_eq!(encode_gif(W, H, FrameRate::FPS_25, std::iter::empty::<&[u8]>(), &Control::default()).expect_err("empty").kind(), ErrorKind::Invalid);
}

#[test]
fn mkv_and_fragmented_copies_decode_identically_to_the_mp4() {
    let mp4 = encode_video(VideoCodec::H264, None, false, 20);
    let want = open("a.mp4", mp4.clone()).frame_number(13, &Control::default()).expect("frame").to_rgba8();
    let d = Demuxer::open_bytes(mp4, &Limits::default()).expect("demux");
    let (mkv, _) = remux_to_vec(&d, &RemuxOptions::new(OutputContainer::Matroska), &Control::default()).expect("mkv");
    let got = open("a.mkv", mkv.clone()).frame_number(13, &Control::default()).expect("mkv frame").to_rgba8();
    assert_eq!(got, want, "Matroska copy decodes to the same pixels");
    // Matroska back to MP4 and the fragmented/CMAF form
    let again = Demuxer::open_bytes(mkv, &Limits::default()).expect("demux mkv");
    let (mp4b, _) = remux_to_vec(&again, &RemuxOptions::new(OutputContainer::Mp4), &Control::default()).expect("mp4");
    assert_eq!(open("b.mp4", mp4b).frame_number(13, &Control::default()).expect("frame").to_rgba8(), want);
    let mut so = SegmentOptions::new();
    so.target_ms = 400;
    let stream = segment(&d, &so, &Control::default()).expect("segments");
    assert!(stream.segments.len() >= 2);
    let mut whole = stream.init.clone();
    stream.segments.iter().for_each(|s| whole.extend_from_slice(&s.data));
    assert_eq!(open("c.mp4", whole).frame_number(13, &Control::default()).expect("frame").to_rgba8(), want);
}

#[test]
fn limits_stop_oversized_pictures_and_requests() {
    let bytes = encode_video(VideoCodec::H264, None, false, 3);
    let mut l = Limits::default();
    l.max_frame_pixels = 100;
    let f = MediaFile::open_bytes("a.mp4", bytes.clone(), &l, &Control::default()).expect("opens");
    assert_eq!(f.frame_at(Tick::ZERO, &Control::default()).expect_err("too large").kind(), ErrorKind::LimitExceeded);
    let mut l = Limits::default();
    l.max_batch_frames = 2;
    let f = MediaFile::open_bytes("a.mp4", bytes.clone(), &l, &Control::default()).expect("opens");
    assert_eq!(f.frames(0, 3, &Control::default()).expect_err("batch").kind(), ErrorKind::LimitExceeded);
    assert_eq!(f.frames(0, 2, &Control::default()).expect("two frames").len(), 2);
    let mut l = Limits::default();
    l.max_input_bytes = 10;
    assert_eq!(MediaFile::open_bytes("a.mp4", bytes, &l, &Control::default()).expect_err("input").kind(), ErrorKind::LimitExceeded);
}

#[test]
fn cancelled_decode_reports_cancelled() {
    let f = open("a.mp4", encode_video(VideoCodec::H264, None, false, 3));
    let token = filmcraft_lib::CancelToken::new();
    token.cancel();
    let c = Control::new().with_cancel(token);
    assert_eq!(f.frame_at(Tick::ZERO, &c).expect_err("cancelled").kind(), ErrorKind::Cancelled);
    let c = Control::new().with_timeout(std::time::Duration::ZERO);
    assert_eq!(f.frame_at(Tick::ZERO, &c).expect_err("deadline").kind(), ErrorKind::DeadlineExceeded);
}

#[test]
fn hostile_media_never_panics_the_decoder() {
    let base = encode_video(VideoCodec::H264, None, false, 6);
    let mut seed = 0xD1B5_4A32_D192_ED03u64;
    for round in 0..200 {
        let mut b = base.clone();
        if round % 4 == 0 {
            b.truncate(b.len() * (round / 4 + 1) / 51);
        } else {
            for _ in 0..6 {
                seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
                let at = (seed >> 33) as usize % b.len();
                b[at] ^= 1 << ((seed >> 20) & 7);
            }
        }
        let r = std::panic::catch_unwind(|| {
            if let Ok(f) = MediaFile::open_bytes("x.mp4", b, &Limits::strict(), &Control::default()) {
                for n in 0..6 {
                    let _ = f.frame_number(n, &Control::default());
                }
                let _ = f.audio_window(0, 0, 1000, 48_000, &Control::default());
            }
        });
        assert!(r.is_ok(), "decoder panicked in round {round}");
    }
}

// ---- files made by ffmpeg, one per container ---------------------------------------------

static COUNTER: AtomicU64 = AtomicU64::new(0);

/// Run ffmpeg with `args` writing `out_name`; `None` (after a loud skip) when ffmpeg is missing or
/// cannot make the file.
fn ffmpeg_file(context: &str, out_name: &str, args: &[&str]) -> Option<Vec<u8>> {
    let ff = filmcraft_testkit::oracle::ffmpeg_or_skip(context)?;
    let dir = std::env::temp_dir().join(format!("filmcraft-lib-{}-{}", std::process::id(), COUNTER.fetch_add(1, Ordering::SeqCst)));
    std::fs::create_dir_all(&dir).expect("temp dir");
    let out = dir.join(out_name);
    let status = Command::new(ff).args(["-hide_banner", "-loglevel", "error", "-y"]).args(args).arg(&out).output().expect("run ffmpeg");
    let bytes = std::fs::read(&out).ok();
    if dir.starts_with(std::env::temp_dir()) {
        let _ = std::fs::remove_dir_all(&dir);
    }
    if bytes.is_none() {
        filmcraft_testkit::oracle::skip(context, &format!("ffmpeg could not make the file: {}", String::from_utf8_lossy(&status.stderr)));
    }
    bytes
}

const VIDEO_SRC: [&str; 4] = ["-f", "lavfi", "-i", "testsrc2=size=128x96:rate=25:duration=1"];
const AUDIO_SRC: [&str; 4] = ["-f", "lavfi", "-i", "sine=frequency=440:sample_rate=48000:duration=1"];

fn check_container(name: &str, bytes: Vec<u8>, expect_video: bool, expect_audio: bool) {
    let p = probe_bytes(name, bytes.clone(), &Limits::default(), &Control::default()).unwrap_or_else(|e| panic!("{name}: probe: {e}"));
    let file = open(name, bytes);
    let info = file.info();
    assert_eq!(info.has_video(), expect_video, "{name} video");
    assert_eq!(info.has_audio(), expect_audio, "{name} audio");
    if expect_video {
        let v = info.video.as_ref().expect("video");
        assert_eq!((v.width, v.height), (128, 96), "{name}");
        let n = p.frame_count().expect("count").value();
        assert!((24..=26).contains(&n), "{name}: {n} frames");
        let mid = file.frame_at(Tick::from_seconds_f64(0.5), &Control::default()).unwrap_or_else(|e| panic!("{name}: mid frame: {e}"));
        let rgba = mid.to_rgba8();
        assert_eq!(rgba.len(), 128 * 96 * 4);
        assert!(rgba.as_chunks::<4>().0.iter().any(|p| p[0] != p[1] || p[1] != p[2]), "{name}: the picture is blank grey");
    }
    if expect_audio {
        let a = file.audio_window(0, 12_000, 4800, 48_000, &Control::default()).unwrap_or_else(|e| panic!("{name}: audio: {e}"));
        assert_eq!(a.frames(), 4800, "{name}");
        let peak = a.peaks().into_iter().fold(0f32, f32::max);
        assert!(peak > 0.1, "{name}: silent audio (peak {peak})");
    }
}

macro_rules! oracle_container {
    ($test:ident, $file:expr, $video:expr, $audio:expr, $codec_args:expr) => {
        #[test]
        fn $test() {
            let mut args: Vec<&str> = Vec::new();
            if $video {
                args.extend(VIDEO_SRC);
            }
            if $audio {
                args.extend(AUDIO_SRC);
            }
            args.extend($codec_args);
            if let Some(bytes) = ffmpeg_file(stringify!($test), $file, &args) {
                check_container(stringify!($test), bytes, $video, $audio);
            }
        }
    };
}

