#[test]
fn matroska_files_from_other_muxers_remux_to_mp4_and_decode() {
    let args: Vec<&str> =
        VIDEO_SRC.iter().chain(AUDIO_SRC.iter()).copied().chain(["-c:v", "libx264", "-pix_fmt", "yuv420p", "-bf", "2", "-c:a", "aac", "-shortest"]).collect();
    let Some(mkv) = ffmpeg_file("ffmpeg_mkv_to_mp4", "a.mkv", &args) else { return };
    let d = Demuxer::open_bytes(mkv.clone(), &Limits::default()).expect("demux");
    assert_eq!(d.tracks().len(), 2);
    let (mp4, rep) = remux_to_vec(&d, &RemuxOptions::new(OutputContainer::Mp4), &Control::default()).expect("remux");
    assert_eq!(rep.copied.len(), 2);
    let a = open("a.mkv", mkv).frame_number(10, &Control::default()).expect("mkv frame").to_rgba8();
    let b = open("a.mp4", mp4).frame_number(10, &Control::default()).expect("mp4 frame").to_rgba8();
    assert_eq!(a, b, "same packets decode to the same picture in either container");
}

#[test]
fn webm_remux_from_matroska_vp9() {
    let args: Vec<&str> =
        VIDEO_SRC.iter().chain(AUDIO_SRC.iter()).copied().chain(["-c:v", "libvpx-vp9", "-b:v", "300k", "-c:a", "libopus", "-shortest"]).collect();
    let Some(webm) = ffmpeg_file("webm_to_mp4_to_webm", "a.webm", &args) else { return };
    let d = Demuxer::open_bytes(webm, &Limits::default()).expect("demux");
    // VP9 + Opus have MP4 mappings; the vpcC is derived from the first keyframe
    let (mp4, _) = remux_to_vec(&d, &RemuxOptions::new(OutputContainer::Mp4), &Control::default()).expect("webm -> mp4");
    let m = Demuxer::open_bytes(mp4.clone(), &Limits::default()).expect("mp4 demux");
    assert_eq!(m.codec_string(0).map(|s| s.starts_with("vp09.00")), Some(true));
    assert_eq!(m.codec_string(1).as_deref(), Some("Opus"));
    let back = Demuxer::open_bytes(mp4, &Limits::default()).expect("demux");
    let (webm2, _) = remux_to_vec(&back, &RemuxOptions::new(OutputContainer::WebM), &Control::default()).expect("mp4 -> webm");
    assert_eq!(&webm2[..4], &[0x1A, 0x45, 0xDF, 0xA3]);
    let f = open("b.webm", webm2).frame_number(5, &Control::default()).expect("decode after the round trip");
    assert_eq!((f.width, f.height), (128, 96));
}
